function pf_reset_root_color() {$options = array("pf_theme_root_color_primary" => "#20A0FF","pf_theme_root_color_white" => "#FFFFFF","pf_theme_root_color_gray_0" => "#1F2D3D","pf_theme_root_color_gray_1" => "#475669","pf_theme_root_color_gray_2" => "#657487","pf_theme_root_color_gray_3" => "#738192","pf_theme_root_color_gray_4" => "#8492A6","pf_theme_root_color_gray_5" => "#99A9BF","pf_theme_root_color_gray_6" => "#CAD1DB","pf_theme_root_color_gray_7" => "#D8E0EA","pf_theme_root_color_gray_8" => "#e6eaf0",//EFF2F7
"pf_theme_root_color_gray_9" => "#F0F2F7","pf_enable_dark_color" => "checked","pf_theme_root_dark_color_primary" => "#20A0FF","pf_theme_root_dark_color_white" => "#34425A","pf_theme_root_dark_color_gray_0" => "#000000","pf_theme_root_dark_color_gray_1" => "#EFF2F7","pf_theme_root_dark_color_gray_2" => "#D8E0EA","pf_theme_root_dark_color_gray_3" => "#CAD1DB","pf_theme_root_dark_color_gray_4" => "#99A9BF","pf_theme_root_dark_color_gray_5" => "#738192","pf_theme_root_dark_color_gray_6" => "#657487","pf_theme_root_dark_color_gray_7" => "#56687F","pf_theme_root_dark_color_gray_8" => "#475669","pf_theme_root_dark_color_gray_9" => "#28374A",);foreach ($options as $key => $value) {update_option($key,$value);}}if (get_option("pf_theme_root_color_primary") === false) {pf_reset_root_color();}add_filter( 'modify_pandastudio_options', function ($options) {$new_file = file_get_contents("options.json",1);$new_arr = json_decode($new_file,true);$newOptions = array_merge($options,$new_arr);return $newOptions;});add_filter( 'modify_pandastudio_translation_array', function ($translation_array) {$color = array('light'=>array("primary" => _opt('pf_theme_root_color_primary'),"white" => _opt('pf_theme_root_color_white'),"gray_0" => _opt('pf_theme_root_color_gray_0'),"gray_1" => _opt('pf_theme_root_color_gray_1'),"gray_2" => _opt('pf_theme_root_color_gray_2'),"gray_3" => _opt('pf_theme_root_color_gray_3'),"gray_4" => _opt('pf_theme_root_color_gray_4'),"gray_5" => _opt('pf_theme_root_color_gray_5'),"gray_6" => _opt('pf_theme_root_color_gray_6'),"gray_7" => _opt('pf_theme_root_color_gray_7'),"gray_8" => _opt('pf_theme_root_color_gray_8'),"gray_9" => _opt('pf_theme_root_color_gray_9')));if (_opt('pf_enable_dark_color')) {$color['dark'] = array("primary" => _opt('pf_theme_root_dark_color_primary'),"white" => _opt('pf_theme_root_dark_color_white'),"gray_0" => _opt('pf_theme_root_dark_color_gray_0'),"gray_1" => _opt('pf_theme_root_dark_color_gray_1'),"gray_2" => _opt('pf_theme_root_dark_color_gray_2'),"gray_3" => _opt('pf_theme_root_dark_color_gray_3'),"gray_4" => _opt('pf_theme_root_dark_color_gray_4'),"gray_5" => _opt('pf_theme_root_dark_color_gray_5'),"gray_6" => _opt('pf_theme_root_dark_color_gray_6'),"gray_7" => _opt('pf_theme_root_dark_color_gray_7'),"gray_8" => _opt('pf_theme_root_dark_color_gray_8'),"gray_9" => _opt('pf_theme_root_dark_color_gray_9'));}$translation_array['color'] = $color;return $translation_array;});add_action( 'get_header', function() {wp_register_script('chromatology',_URL(__DIR__).'/script.build.js',array(),filemtime(__DIR__.'/script.build.js'));wp_enqueue_script( 'chromatology' );},9);add_action('pandastudio_framework_options_submenu_data',function(){?><tr><th><label><?php _et8('重置主题默认配色'); ?></label></th><td><a class="button" href="<?php echo add_query_arg('action','reset_theme_color',admin_url('admin.php')); ?>"><?php _et8('重置配色'); ?></a><p class="description"><?php _et8('对于允许自定义主题配色的高级版，可恢复主题默认配色'); ?></p></td></tr><?php
},3);add_action("admin_action_reset_theme_color",function(){if (current_user_can('manage_options')) {pf_reset_root_color();wp_redirect( add_query_arg('message',_t8('主题色彩已成功重置'),wp_get_referer()) );}});add_action( 'rest_api_init', function() {register_rest_route( 'pandastudio/revival', '/admin-save-color/', array('methods' => 'post','callback' => 'pf_admin_save_color',));});function pf_admin_save_color($data) {if (current_user_can('manage_options')) {$colors = json_decode($data->get_body(),true);foreach ($colors as $name => $value) {update_option($name,$value);}return $colors;} else {return ['is_error'=>'true','error_message'=>_t8('保存配色失败：无权限！')];}}